result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/sim.ts", "content": "// Deterministic particle soak test.
//
// 200 particles with Q16.16 fixed-point positions (stored as plain numbers
// holding the scaled integer; all values stay well below 2^53, so number
// arithmetic is exact) bouncing inside a 1000x1000 box. Initial velocities
// come from a seeded xorshift32 RNG. After exactly 10000 fixed ticks a
// FNV-1a 32-bit hash is computed over every particle state.
//
// No floating point, no Math.random, no Date.now anywhere in the simulation:
// identical seeds produce byte-identical state streams.

export const NUM_PARTICLES = 200;
export const TICKS = 10000;
export const BOX = 1000;

const SCALE = 65536; // Q16.16
const BOX_MAX = BOX * SCALE; // inclusive upper bound of the box interior

/** xorshift32; returns a function producing successive uint32 values. */
export function makeRng(seed: number): () => number {
  // Seed 0 is a fixed point for xorshift32; map it to a nonzero value.
  let s = seed >>> 0;
  if (s === 0) s = 0x9e3779b9;
  return () => {
    s ^= s << 13;
    s >>>= 0;
    s ^= s >>> 17;
    s ^= s << 5;
    s >>>= 0;
    return s;
  };
}

export interface Particle {
  /** Fixed-point position (Q16.16), always within [0, BOX_MAX]. */
  x: number;
  y: number;
  /** Fixed-point velocity (Q16.16) per tick. */
  vx: number;
  vy: number;
}

/** Max initial speed component: 3.0 px/tick in Q16.16. */
const MAX_VEL = 3 * SCALE;

/** Initialize all particles from the seeded RNG (positions + velocities). */
export function initParticles(seed: number): Particle[] {
  const rng = makeRng(seed);
  const particles: Particle[] = new Array(NUM_PARTICLES);
  for (let i = 0; i < NUM_PARTICLES; i++) {
    const x = rng() % BOX_MAX;
    const y = rng() % BOX_MAX;
    const vx = (rng() % (2 * MAX_VEL + 1)) - MAX_VEL;
    const vy = rng() % (2 * MAX_VEL + 1) - MAX_VEL;
    particles[i] = { x, y, vx, vy };
  }
  return particles;
}

/**
 * Advance one fixed tick. Velocities are bounded well below the box size,
 * so a single reflection per axis is always sufficient to stay in range.
 */
export function step(particles: Particle[]): void {
  for (let i = 0; i < particles.length; i++) {
    const p = particles[i];

    p.x += p.vx;
    if (p.x < 0) {
      p.x = -p.x;
      p.vx = -p.vx;
    } else if (p.x > BOX_MAX) {
      p.x = 2 * BOX_MAX - p.x;
      p.vx = -p.vx;
    }

    p.y += p.vy;
    if (p.y < 0) {
      p.y = -p.y;
      p.vy = -p.vy;
    } else if (p.y > BOX_MAX) {
      p.y = 2 * BOX_MAX - p.y;
      p.vy = -p.vy;
    }
  }
}

/** FNV-1a, 32-bit. */
export function fnv1a(bytes: Uint8Array): number {
  let h = 0x811c9dc5;
  for (let i = 0; i < bytes.length; i++) {
    h ^= bytes[i];
    h = Math.imul(h, 0x01000193) >>> 0;
  }
  return h >>> 0;
}

function putU32(buf: Uint8Array, offset: number, value: number): void {
  const u = value >>> 0;
  buf[offset] = u & 0xff;
  buf[offset + 1] = (u >>> 8) & 0xff;
  buf[offset + 2] = (u >>> 16) & 0xff;
  buf[offset + 3] = (u >>> 24) & 0xff;
}

/** Serialize final state and hash it. */
export function hashState(particles: Particle[]): number {
  const buf = new Uint8Array(NUM_PARTICLES * 16);
  for (let i = 0; i < NUM_PARTICLES; i++) {
    const p = particles[i];
    const o = i * 16;
    putU32(buf, o, p.x);
    putU32(buf, o + 4, p.y);
    putU32(buf, o + 8, p.vx);
    putU32(buf, o + 12, p.vy);
  }
  return fnv1a(buf);
}

/** Run the full soak: init with seed, advance TICKS ticks, hash the state. */
export function simulate(seed: number): number {
  const particles = initParticles(seed);
  for (let t = 0; t < TICKS; t++) step(particles);
  return hashState(particles);
}

// ---------------------------------------------------------------------------
// CLI: node dist/sim.js --seed 42   ->   prints the hash to stdout
// ---------------------------------------------------------------------------

function cliMain(): void {
  const args = process.argv.slice(2);
  let seed = 42;
  const idx = args.indexOf("--seed");
  if (idx >= 0 && args[idx + 1] !== undefined) {
    const parsed = Number.parseInt(args[idx + 1], 10);
    if (!Number.isNaN(parsed)) seed = parsed;
  }
  console.log(simulate(seed));
}

if (
  typeof require !== "undefined" &&
  typeof module !== "undefined" &&
  require.main === module
) {
  cliMain();
}
"})
