result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/sim.test.ts", "content": "import { describe, expect, it } from "vitest";
import { execFileSync } from "node:child_process";
import { resolve } from "node:path";
import { simulate, TICKS, initParticles, step, hashState } from "./sim";

const CLI = resolve(__dirname, "dist", "sim.js");

describe("deterministic soak test", () => {
  it("same seed twice gives the same hash (in-process)", () => {
    expect(simulate(42)).toBe(simulate(42));
    expect(simulate(123456789)).toBe(simulate(123456789));
  });

  it("different seed gives a different hash", () => {
    const hashes = new Set<number>();
    for (const seed of [42, 43, 1, 0xdeadbeef, 20260824]) {
      hashes.add(simulate(seed));
    }
    // All five distinct seeds must yield pairwise-distinct hashes.
    expect(hashes.size).toBe(5);
  });

  it("hash is stable across two separate process runs", () => {
    const run = () =>
      execFileSync("node", [CLI, "--seed", "42"], {
        encoding: "utf8",
      }).trim();

    const out1 = run();
    const out2 = run();

    expect(out1).toMatch(/^[0-9]+$/);
    expect(out2).toBe(out1);
  });

  it("CLI output matches the in-process hash for the same seed", () => {
    const stdout = execFileSync("node", [CLI, "--seed", "1337"], {
      encoding: "utf8",
    }).trim();
    expect(stdout).toBe(String(simulate(1337)));
  });

  it("particles stay inside the box for the whole soak", () => {
    const particles = initParticles(7);
    const boxMax = 1000 * 65536;
    let t = 0;
    while (t < TICKS) {
      step(particles);
      t++;
      if (t % 1000 === 0) {
        for (const p of particles) {
          expect(p.x).toBeGreaterThanOrEqual(0);
          expect(p.x).toBeLessThanOrEqual(boxMax);
          expect(Number.isInteger(p.x)).toBe(true);
          expect(p.y).toBeGreaterThanOrEqual(0);
          expect(p.y).toBeLessThanOrEqual(boxMax);
          expect(Number.isInteger(p.y)).toBe(true);
        }
      }
    }
    expect(hashState(particles)).toBe(simulate(7));
  });
});
"})
